pub fn parse_quantity(input: &str) -> Result<u32, QuantityError> {
    let quantity = input.parse::<u32>().map_err(|_| QuantityError::NotANumber)?;
    if quantity == 0 {
        return Err(QuantityError::Zero);
    }
    Ok(quantity)
}

#[derive(Debug, PartialEq)]
pub enum QuantityError {
    NotANumber,
    Zero,
}

