use campus_core::parse_quantity;

#[test]
fn parses_a_quantity() {
    assert_eq!(parse_quantity("4").unwrap(), 4);
}

#[test]
fn rejects_zero() {
    assert_eq!(parse_quantity("0"), Err(campus_core::QuantityError::Zero));
}

#[test]
fn rejects_text() {
    assert_eq!(
        parse_quantity("many"),
        Err(campus_core::QuantityError::NotANumber)
    );
}
